  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artiste-Des-Rues-(Barde).html&quot; title=&quot;Artiste des rues&quot;&gt;Artiste des rues&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artiste-Masqu&#233;-(Barde).html&quot; title=&quot;Artiste masqu&#233;&quot;&gt;Artiste masqu&#233;&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barde-De-Cour-(Barde).html&quot; title=&quot;Barde de cour&quot;&gt;Barde de cour&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barde-Fun&#232;bre-(Barde).html&quot; title=&quot;Barde fun&#232;bre&quot;&gt;Barde fun&#232;bre&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Boucanier-(Barde).html&quot; title=&quot;Boucanier&quot;&gt;Boucanier&lt;/a&gt; (PMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casse-Cou-(Barde).html&quot; title=&quot;Casse-cou&quot;&gt;Casse cou&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;C&#233;l&#233;brit&#233;-(Barde).html&quot; title=&quot;C&#233;l&#233;brit&#233;&quot;&gt;C&#233;l&#233;brit&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chantemer-(Barde).html&quot; title=&quot;Chantemer&quot;&gt;Chantemer&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chanteur-De-Leau-(Barde).html&quot; title=&quot;Chanteur de l’eau&quot;&gt;Chanteur de l&#39;eau&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Ondin-(Race).html&quot; title=&quot;Les ondins&quot;&gt;Ondin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Danseur-Des-Flammes-(Barde).html&quot; title=&quot;Danseur des flammes&quot;&gt;Danseur des flammes&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;magogue-(Barde).html&quot; title=&quot;D&#233;magogue&quot;&gt;D&#233;magogue&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Derviche-(Barde).html&quot; title=&quot;Derviche&quot;&gt;Derviche&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Derviche-De-La-Fleur-De-Laube-(Barde).html&quot; title=&quot;Derviche de l&amp;#39;aube (barde)&quot;&gt;Derviche de l&#39;aube&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tective-(Barde).html&quot; title=&quot;D&#233;tective&quot;&gt;D&#233;tective&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Diva-Ch&#233;liaxienne-(Barde).html&quot; title=&quot;Diva&quot;&gt;Diva&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Jappeur-(Barde).html&quot; title=&quot;Dragon jappeur&quot;&gt;Dragon jappeur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Kobold-(Race).html&quot; title=&quot;Les kobolds&quot;&gt;Kobold&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Duelliste-Des-Arcanes-(Barde).html&quot; title=&quot;Duelliste des arcanes&quot;&gt;Duelliste des arcanes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Farceur-(Barde).html&quot; title=&quot;Farceur&quot;&gt;Farceur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;Gnome&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Frappeson-(Barde).html&quot; title=&quot;Frappeson&quot;&gt;Frappeson&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Geisha-(Barde).html&quot; title=&quot;Geisha&quot;&gt;Geisha&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Intellectuel-(Barde).html&quot; title=&quot;Intellectuel&quot;&gt;Intellectuel&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Interpr&#232;te-De-Ballades-Argent&#233;es-(Barde).html&quot; title=&quot;Interpr&#232;te de ballades argent&#233;es&quot;&gt;Interpr&#232;te de ballades argent&#233;es&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marchand-De-Sable-(Barde).html&quot; title=&quot;Marchand de sable&quot;&gt;Marchand de sable&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marionnettiste-Des-Ombres-(Barde).html&quot; title=&quot;Marionnettiste des ombres&quot;&gt;Marionnettiste des ombres&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Wayang-(Race).html&quot; title=&quot;Les wayangs&quot;&gt;Wayang&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Meneur-(Barde).html&quot; title=&quot;Meneur&quot;&gt;Meneur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Messager-Inflexible-(Barde).html&quot; title=&quot;Messager inflexible&quot;&gt;Messager inflexible&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Orateur-Animal-(Barde).html&quot; title=&quot;Orateur animal&quot;&gt;Orateur animal&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phr&#233;nologue-(Barde).html&quot; title=&quot;Phr&#233;nologue&quot;&gt;Phr&#233;nologue&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Prestidigitateur-(Barde).html&quot; title=&quot;Prestidigitateur&quot;&gt;Prestidigitateur&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Scalde-Sauvage-(Barde).html&quot; title=&quot;Scalde sauvage&quot;&gt;Scalde sauvage&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Soignechant-(Barde).html&quot; title=&quot;Soignechant&quot;&gt;Soignechant&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Voix-De-La-Nature-(Barde).html&quot; title=&quot;Voix de la nature&quot;&gt;Voix de la nature&lt;/a&gt; (MCA)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;S’il appr&#233;cie la repr&#233;sentation, le prestidigitateur voit aussi cela comme un moyen d’utiliser une partie des &#233;nergies universelles et de les canaliser.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Repr&#233;sentation bardique&lt;a class=&quot;headeranchor&quot; id=&quot;Repr&#233;sentation_bardique_0&quot; href=&quot;#Repr&#233;sentation_bardique_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 
Le prestidigitateur ma&#238;trise les types de &lt;a class=&quot;pagelink&quot; href=&quot;Barde#Representationbardique.html&quot; title=&quot;repr&#233;sentation bardique&quot;&gt;repr&#233;sentation bardique&lt;/a&gt; suivants.&lt;br /&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;i&gt;Fabrication d’enchantement (Sur).&lt;/i&gt; Un prestidigitateur manipule les &#233;nergies magiques. Ses alli&#233;s b&#233;n&#233;ficient d’un bonus de +1 sur leurs tests de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;Concentration&lt;/a&gt;, ainsi que sur leurs jets d’attaque lorsqu’ils font usage de sorts et de pouvoirs magiques. Ce bonus augmente de +1 au niveau 5, +1 par tranche de six niveaux au-del&#224;. Cette aptitude utilise une composante verbale et visuelle et remplace &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#inspiration vaillante&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;inspiration vaillante&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;i&gt;Suppression de sortil&#232;ge (Sur).&lt;/i&gt; Au niveau 8, un prestidigitateur peut contrer les sorts de ses adversaires. Il commence la repr&#233;sentation et garde une trace du nombre de rounds pendant lesquels elle est utilis&#233;e. Dans le m&#234;me temps, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;, il peut tenter de contrer un sort qu’il aura reconnu gr&#226;ce &#224; &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt;, et ce tant que le niveau de ce sort est inf&#233;rieur ou &#233;gal au nombre total de rounds qu’a dur&#233; sa repr&#233;sentation. Cette tentative de contre-sort fonctionne de la m&#234;me mani&#232;re que &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dissipation-De-La-Magie.html&quot; title=&quot;Dissipation de la magie&quot;&gt;dissipation de la magie&lt;/a&gt;&lt;/i&gt; et le &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; sera le niveau du barde dans sa classe. En cas de r&#233;ussite, la repr&#233;sentation bardique cesse imm&#233;diatement. Cette aptitude d&#233;pendant du langage utilise une composante verbale et remplace &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#Chant_funeste_Sur_6&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;chant funeste&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;i&gt;Ma&#238;trise de la m&#233;tamagie (Ext).&lt;/i&gt; Au niveau 14, le prestidigitateur peut appliquer les effets d’un &lt;a class=&quot;pagelink&quot; href=&quot;Dons#Donmetamagie.html&quot; title=&quot;don de m&#233;tamagie&quot;&gt;don de m&#233;tamagie&lt;/a&gt; &#224; un sort qu’il est sur le point de lancer, sans rallonger le temps d’incantation. Le barde doit toujours y consacrer un &lt;a class=&quot;pagelink&quot; href=&quot;Emplacement-De-Sort.html&quot; title=&quot;emplacement de sort&quot;&gt;emplacement de sort&lt;/a&gt; de niveau sup&#233;rieur. La repr&#233;sentation cesse imm&#233;diatement. Cette aptitude d&#233;pendant du langage utilise une composante verbale et remplace &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#M&#233;lodie_effrayante_Mag_9&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;m&#233;lodie effrayante&lt;/a&gt;. &lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Talent magique (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Talent_magique_Ext_1&quot; href=&quot;#Talent_magique_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 
Un prestidigitateur gagne un bonus &#233;gal &#224; la moiti&#233; de son niveau de barde sur les tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res) et d’&lt;a class=&quot;pagelink&quot; href=&quot;Utilisation-Dobjets-Magiques.html&quot; title=&quot;Utilisation d&amp;#39;objets magiques&quot;&gt;Utilisation d’objets magiques&lt;/a&gt;. Cette aptitude remplace &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#Savoir_bardique_Ext_2&quot; title=&quot;Le barde&quot;&gt;savoir bardique&lt;/a&gt;. &lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Science du contresort&lt;a class=&quot;headeranchor&quot; id=&quot;Science_du_contresort_2&quot; href=&quot;#Science_du_contresort_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le prestidigitateur gagne le don &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Contresort.html&quot; title=&quot;Science du contresort&quot;&gt;Science du contresort&lt;/a&gt; en bonus &#224; la place de l’aptitude de classe &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#Contre-chant_Sur_0&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;contrechant&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Repr&#233;sentation &#233;tendue (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Repr&#233;sentation_&#233;tendue_Sur_3&quot; href=&quot;#Repr&#233;sentation_&#233;tendue_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 
Au niveau 2 et par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;, un prestidigitateur peut &#233;tendre la dur&#233;e de sa repr&#233;sentation bardique apr&#232;s qu’il ait cess&#233; de se concentrer. Il doit sacrifier un &lt;a class=&quot;pagelink&quot; href=&quot;Emplacement-De-Sort.html&quot; title=&quot;emplacement de sort&quot;&gt;emplacement de sort&lt;/a&gt;, ce qui prolonge les effets de cette repr&#233;sentation durant 1 round par niveau du sort sacrifi&#233;. Il ne peut y consacrer qu’un seul sort &#224; la fois. Cette aptitude n’affecte pas les repr&#233;sentations qui prennent effet apr&#232;s un certain nombre de rounds, et remplace &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#&#201;rudition_Ext_6&quot; title=&quot;Le barde&quot;&gt;&#233;rudition&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;R&#233;pertoire &#233;tendu (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;R&#233;pertoire_&#233;tendu_Sur_4&quot; href=&quot;#R&#233;pertoire_&#233;tendu_Sur_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2 et tous les quatre niveaux au-del&#224;, un prestidigitateur peut choisir un nouveau sort parmi ceux disponibles pour n’importe quelle classe de jeteur de sort profane, et l’ajouter &#224; la liste de ceux qu’il connait. Le sortil&#232;ge doit &#234;tre d’un niveau accessible. Cette aptitude remplace &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#Versatilit&#233;_artistique_Ext_5&quot; title=&quot;Le barde&quot;&gt;versatilit&#233; artistique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pacte magique (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Pacte_magique_Ext_5&quot; href=&quot;#Pacte_magique_Ext_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 5, le prestidigitateur gagne l’aptitude de magicien &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html#PACTEMAGIQUE&quot; title=&quot;Le magicien&quot;&gt;pacte magique&lt;/a&gt;. Il ne peut choisir ni un familier, ni une arme comme objet f&#233;tiche. Cette aptitude remplace &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#Ma&#238;tre_du_savoir_Ext_7&quot; title=&quot;Le barde&quot;&gt;ma&#238;tre du savoir&lt;/a&gt;. &lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Ma&#238;trise des baguettes (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Ma&#238;trise_des_baguettes_Ext_6&quot; href=&quot;#Ma&#238;trise_des_baguettes_Ext_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 10 et lorsqu’il utilise une baguette contenant un sort pr&#233;sent sur sa liste, le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; sera calcul&#233; en tenant compte du modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; du barde. Au niveau 16, il utilisera son &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; &#224; la place de celui de la baguette. Cette aptitude remplace &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#Touche-&#224;-tout_Ext_8&quot; title=&quot;Le barde&quot;&gt;touche &#224; tout&lt;/a&gt;.
